side=30;
//thickness of the board
thick=2.2;
edge_thick=3;
//coefficient of the thickness of the board
edge_height_coef=1.5;//[1:0.1:3]

//printer tolerance (only affect "color 02" parts)
tolerance=0.2;//[0:0.05:0.7]
//definition (only affect corners)
$fn=60;
render="Test part";//[Corner color 01,Corner color 02,Edge color 01,Edge color 02,Center color 01,Center color 02,Test part]

////////
module slot() {
translate([-side/2,0,-thick/2-0.2]) rotate([0,0,180]) translate([0.2,0,0]) hull() {for(i=[-1,1]) translate([-0.5-2*tolerance/1.75,i*(0.866+2*tolerance),0]) cylinder(d=8,h=thick/2+0.5,$fn=3);}
}
module couleur01(a) {
    cube([side,side,thick],center=true);
    for(i=[0,90]) rotate([0,0,i])
    translate([-side/2,0,-thick/2]) cylinder(d=10,h=thick/2,$fn=3);
    if (a==2) {
        for(i=[0,-90]) rotate([0,0,i])
        translate([-side/2,side/2,-thick/2]) cube([side,edge_thick,edge_height_coef*thick]);
        difference() {
            translate([side/2,side/2,-thick/2]) cylinder(r=edge_thick,h=edge_height_coef*thick);
            cube([side,side,2*edge_height_coef*thick],center=true);
        }
    }
    if (a==3) {
        rotate([0,0,180])
        translate([-side/2,0,-thick/2]) cylinder(d=10,h=thick/2,$fn=3);
        translate([-side/2,side/2,-thick/2]) cube([side,edge_thick,edge_height_coef*thick]);
    }
    else if (a==4) {
        for(i=[180,-90]) rotate([0,0,i])
        translate([-side/2,0,-thick/2]) cylinder(d=10,h=thick/2,$fn=3);
    }
    else {};
}

module couleur02(a) {
    difference() {
        cube([side,side,thick],center=true);
        for(i=[0,90]) rotate([0,0,i])
        slot();
        if (a==3) {
            rotate([0,0,180]) slot();
        }
        else if (a==4) {
            for(i=[180,-90]) rotate([0,0,i]) slot();
        }
        else {};
    }
    if (a==2) {
        for(i=[0,-90]) rotate([0,0,i])
        translate([-side/2,side/2,-thick/2]) cube([side,edge_thick,edge_height_coef*thick]);
        difference() {
            translate([side/2,side/2,-thick/2]) cylinder(r=edge_thick,h=edge_height_coef*thick);
            cube([side,side,2*edge_height_coef*thick],center=true);
        }
    }
    if (a==3) {
        translate([-side/2,side/2,-thick/2]) cube([side,edge_thick,edge_height_coef*thick]);
    }
}

if (render=="Corner color 01") {
    couleur01(2);
}
else if (render=="Corner color 02") {
    couleur02(2);
}
else if (render=="Edge color 01") {
    couleur01(3);
}
else if (render=="Edge color 02") {
    couleur02(3);
}
else if (render=="Center color 01") {
    couleur01(4);
}
else if (render=="Center color 02") {
    couleur02(4);
}
else if (render=="Test part") {
    rotate([0,0,180]) translate([-1.5,0,0]) difference() {
        translate([-7.5,0,0]) cube([15,15,thick],center=true);
        translate([-30/2,0,-thick/2-0.2]) rotate([0,0,180]) translate([0.2,0,0]) hull() {for(i=[-1,1]) translate([-0.5-2*tolerance/1.75,i*(0.866+2*tolerance),0]) cylinder(d=8,h=thick/2+0.5,$fn=3);}
    }
    translate([-1.5,0,0]) union() {
        translate([-7.5,0,0]) cube([15,15,thick],center=true);
        translate([-30/2,0,-thick/2]) cylinder(d=10,h=thick/2,$fn=3);
    }
}

modelSources.Clip_Stand_v1-0.scad:
// Length of the stand
_length = 160.0;

// height of the stand
_height = 24.0;

// Curvature of the stand (lower values for a flatter arc, 100 for a semicircle)
_curvature = 99; //[50:100]

// Thickness of the stand
_thickness = 3;

// Radius at the ends where it clips to the device
_clip_radius = 2.5;

// How far around the device the clips run
_clip_angle = 100; //[60:180]



////////////////////////////////////////////////////////////////////////



// only works from [0 to 180] degrees, runs clockwise from 12 o'clock
module smallArc(radius0, radius1, angle, depth) {
	thickness = radius1 - radius0;
	eps = 0.1;

	union() {
		difference() {
			// full arc
			cylinder(r=radius1, h=depth, center=true);
			cylinder(r=radius0, h=depth+2*eps, center=true);

			for(z=[0, 180 - angle]) {
				rotate([0,0,z])
				translate([-radius1,0,0])			
				cube(size = [radius1*2, radius1*2, depth+eps], center=true);
			}
		}
	}
}



// arc from [0 to 360] degrees with rounded ends, runs clockwise from 12 o'clock, rounded tips not included in angle computation
module roundArc(radius0, radius1, angle, depth) {
	thickness = radius1 - radius0;
	cutAngle = 360-angle;
	centerRadius = (radius0 + radius1)/2.0;
	union() {
		if (angle > 180) {
			smallArc(radius0, radius1, 180, depth);
			rotate([0,0,-180]) {
				smallArc(radius0, radius1, angle-180, depth);
			}
		} else {
			smallArc(radius0, radius1, angle, depth);
		}

		// round ends
		for(t = [ [0,centerRadius,0], 
					 [centerRadius * -sin(cutAngle), centerRadius * cos(cutAngle),0] ]) {
			translate(t) {
				cylinder(r=thickness/2, h=depth, center=true);
			}
		}
	}
}

module makeStand(arcRadius, angle, height, outerThickness, clipRadius, clipAngle) {
	ir = arcRadius;
	or = ir + outerThickness;
	cx = (ir-clipRadius)*sin(angle/2);
	cy = (ir-clipRadius)*cos(angle/2);

	union() {

		//	spine
		rotate([0,0,angle/2]) {
			smallArc(ir, or, angle, height, $fn=180);
		}

		// clip
		for (m=[1,0]) {
			mirror([m,0,0]) {
				translate([cx, cy, 0])
				rotate([0,0,-angle/2]) {
					roundArc(clipRadius, clipRadius+outerThickness, clipAngle, height, $fn=45);
				}
			}
		}
	}
}

module make() {
	radius = _length / (2 *(_curvature/100));
	angle = 2 * asin(_length/(2*radius));

	translate([0,-radius,_height/2]) {
			makeStand(radius, 
					  angle, 
					  _height, 
					  _thickness, 
					  _clip_radius,
					  _clip_angle);
		}
}

make();

modelSources.ContourHandshake_28878.scad:
// Contour Handshake™ Business Card
card_w = 88.9;
card_h = 50.8;
corner_radius = 3;
base_thickness = 1.6;
ridge_height = 0.8;
line_width = 2.2;
line_spacing = 2.8;
curve_amplitude = 6;
curve_bias = 4;
swirl_strength = 0.25;

module rounded_rect_2d(w, h, r) {
  offset(r=r) offset(delta=-r) square([w, h], center=true);
}

module card_base() {
  linear_extrude(height=base_thickness)
    rounded_rect_2d(card_w, card_h, corner_radius);
}

module ridge_field(height=ridge_height) {
  for (i = [-18:18]) {
    x = i * line_spacing;
    phase = (x / (card_w / 2)) * swirl_strength;
    translate([x, 0, base_thickness])
      linear_extrude(height=height)
        offset(r=0.6) offset(delta=-0.6)
          polygon([
            [-card_h, sin(i*0.55 + phase)*curve_amplitude + curve_bias],
            [ card_h, cos(i*0.55 - phase)*curve_amplitude - curve_bias],
            [ card_h, cos(i*0.55 - phase)*curve_amplitude - curve_bias + line_width],
            [-card_h, sin(i*0.55 + phase)*curve_amplitude + curve_bias + line_width]
          ]);
  }
}

module contour_handshake_card() {
  union() {
    card_base();
    ridge_field();
  }
}

contour_handshake_card();

