			branch_cross_section_bounds_size_cutoff = my_branch_diameter_cutoff,

			last_branch_root_scale = 1,
			last_branch_length = my_trunk_length,

			random_seed = false,
			manual_seed = seed


		)
		{
			rotate([0,0,90])
			circle(r = trunk_radius, $fn = branch_cross_section_shape);
