// Boton charro by Magonegro JUL-2016
// Number of rings:
Rings=5;
// Ring width multiple of the nozzle size (mm):
RingWidth=2.4;
// Min Radius (mm):
MINRadius=10;
// Separation between rings (mm typ 0.8):
Separation=0.8;
// Resolution (min.100 facets):
Facets=100;

/* [Hidden] */
// Hidden settings for normal users.
// Height should be calculated so that rings can be holded together.
Height=(MINRadius*2)-RingWidth; // Forces the hole of the inner ring 
MaxRadius=MINRadius+(Rings*RingWidth)+(Rings*Separation);
// These are the keyring dimensions, increase it for a larger one (mm) Values choosen for a standard keyring.
KEYRINGRADIUSOuter=6;
KEYRINGRADIUSInner=3;
KEYRINHeightt=4;

module Ring(Radius,Width)
{
difference()
    {
    sphere(r=Radius+Width,center=true,$fn=Facets);
    sphere(r=Radius,center=true,$fn=Facets);
    }
}

module KeyRing()
{
// Ring designed this way for an easy print, not nice but functional.
difference()
    {
    translate([MaxRadius-1,0,-Height/2])
    difference()
        {
        cylinder(r=KEYRINGRADIUSOuter,h=KEYRINHeightt,$fn=Facets);
        cylinder(r=KEYRINGRADIUSInner,h=KEYRINHeightt,$fn=Facets);

        }
    sphere(r=MaxRadius-RingWidth,center=true,$fn=Facets);
    }
}

// Main
intersection()
{
    union()
    {
        for(i=[0:Rings-1])
        {
            Ring(MINRadius+(i*RingWidth)+(i*Separation),RingWidth);
        }
        KeyRing();
    }
        cylinder(r=MaxRadius*2,h=Height,$fn=Facets,center=true);
}    

// Sanity checks
if(MaxRadius>Height*1.6)
{
    echo("<B>Error: Unstable build. Reduce ring number or increase Min radius</B>");
}
if(Separation>RingWidth/2.6)
{
    echo("<B>Too high separation or too low ringwidth</B>");
}

modelSources.Hex_Wrench_Handle.scad:
// Diameter of hole for the hex wrench
hex_size = 2.8;

// Increase slot size by this amount
hole_delta = 0.15;

// Diameter of the handle
handle_diameter = 25;

handle(hex_size);

module handle(hex_size)
{
	hex_radius = (hex_size + hole_delta) / 2;
	hex_size = hex_size + hole_delta;
	handle_radius = handle_diameter / 2;
	knurl_offset = handle_radius * 1.2;
	handle_height = 50;
	slot_width = 1.2 * handle_radius;
	zip_tie_back = 0.6 * handle_radius;
	slot_bottom = 15;

	$fn=40;									// Control quality of mesh

	hole_radius = hex_radius + .2;	// Give a little more room for small hole

	difference()
	{
		union()
		{
			cylinder(h = 5, r1 = handle_radius - 3, r2 = handle_radius);
			translate(v=[0, 0, 5])
				cylinder(h = handle_height - 5, r = handle_radius);
			translate(v=[0, 0, handle_height])
				sphere(handle_radius);
		}

		for (angle = [30:60:360])
			translate(v=[knurl_offset * cos(angle), knurl_offset * sin(angle), 0])
				cylinder(h = handle_height + handle_radius, r = handle_radius / 2.7);

		// Shaft hole
		cylinder(h = handle_height + handle_radius, r = hole_radius);

		// Small cone at bottom
		cylinder(h = 2, r1 = hole_radius + .6, r2 = hole_radius);

		// Slot for the wrench
		translate(v=[0, -hex_size / 2, slot_bottom])
			cube(size = [handle_radius, hex_size, handle_height + handle_radius]);

		// Slot for bend in wrench
		translate(v=[0, -hex_size / 2, slot_bottom - 1.5 * hex_size])
			cube(size = [1.5 * hex_size, hex_size, 2 * hex_size]);

		// Lower slot for zip-tie
		translate(v=[zip_tie_back, -slot_width / 2, slot_bottom - 6])
			cube(size=[3, slot_width, 3]);

		// Upper slot for zip tie
		translate(v=[zip_tie_back, -slot_width / 2, slot_bottom + sin(60) * hex_size - 1])
			cube(size=[3, slot_width, 3]);

		// Zip Tie Opening
		translate(v=[zip_tie_back, slot_width / 4, slot_bottom - 6])
			cube(size=[3, slot_width / 4, 6 + sin(60) * hex_size + 2]);

		translate(v=[zip_tie_back, -slot_width / 2, slot_bottom - 6])
			cube(size=[3, slot_width / 4, 6 + sin(60) * hex_size + 2]);
	}
}

modelSources.Hinged_Box.scad:
$fn = 100;
width = 40;
depth = 40;
height = 15;
wallThickness = 1.5;
hingeOuter = 7;
hingeInner = 4;
hingeInnerSlop = .4;
hingeFingerSlop = .4;
fingerLength = hingeOuter/1.65;
fingerSize = 6.5;
topFingerSize = fingerSize;
pos = -depth/2;
latchWidth = 8;
z = 0;

bottom();
top();

module bottom() {
	union() {
		// main box and cutout
		difference() {
			translate([-width - fingerLength, -depth/2, 0]) {
				cube([width,depth,height]);
			}

			translate([(-width - fingerLength) + wallThickness, -depth/2 + wallThickness, wallThickness]) {
				cube([width - (wallThickness * 2), depth - (wallThickness * 2), height]);
			}

			// latch cutout
			translate([-width - fingerLength + (wallThickness/2), (-latchWidth/2) - (hingeFingerSlop/2), wallThickness]) {
				cube([wallThickness/2 + .1, latchWidth + hingeFingerSlop, height]);
			}


		}

		//latch cylinder
		difference() {
			translate([-width - fingerLength + (wallThickness/2), -latchWidth/2, height - 1]) {
				rotate([-90,0,0]) {
					cylinder(r = 1, h = latchWidth);
				}
			}
			// front wall wipe
			translate([-width - fingerLength - 5, -depth/2,0]) {
				cube([5,depth,height]);
			}
		}

		difference() {
			hull() {
				translate([0,-depth/2,height]) {
					rotate([-90,0,0]) {
						cylinder(r = hingeOuter/2, h = depth);
					}
				}
				translate([-fingerLength - .1, -depth/2,height - hingeOuter]){
					cube([.1,depth,hingeOuter]);
				}
				translate([-fingerLength, -depth/2,height-.1]){
					cube([fingerLength,depth,.1]);
				}
				translate([0, -depth/2,height]){
					rotate([0,45,0]) {
						cube([hingeOuter/2,depth,.01]);
					}
				}
			}
			// finger cutouts

			for  (i = [-depth/2 + fingerSize:fingerSize*2:depth/2]) {
				translate([-fingerLength,i - (fingerSize/2) - (hingeFingerSlop/2),0]) {
					cube([fingerLength*2,fingerSize + hingeFingerSlop,height*2]);
				}
			}
		}

		// center rod
		translate([0, -depth/2, height]) {
			rotate([-90,0,0]) {
				cylinder(r = hingeInner /2, h = depth);
			}
		}
	}
}

module top() {
	union() {
		difference() {
			translate([fingerLength, -depth/2, 0]) {
				cube([width,depth,height - .5]);
			}

			translate([fingerLength + wallThickness, -depth/2 + wallThickness, wallThickness]) {
				cube([width - (wallThickness * 2), depth - (wallThickness * 2), height]);
			}


		}

		//latch
		translate([width + fingerLength - wallThickness - 1.5, (-latchWidth/2), 0]) {
			cube([1.5, latchWidth, height - .5 + 4]);
		}
		translate([width + fingerLength - wallThickness, -latchWidth/2, height - .5 + 3]) {
			rotate([-90,0,0]) {
				cylinder(r = 1, h = latchWidth);
			}
		}

		difference() {
			hull() {
				translate([0,-depth/2,height]) {
					rotate([-90,0,0]) {
						cylinder(r = hingeOuter/2, h = depth);
					}
				}
				translate([fingerLength, -depth/2,height - hingeOuter - .5]){
					cube([.1,depth,hingeOuter - .5]);
				}
				translate([-fingerLength/2, -depth/2,height-.1]){
					cube([fingerLength,depth,.1]);
				}
				translate([0, -depth/2,height]){
					rotate([0,45,0]) {
						cube([hingeOuter/2,depth,.01]);
					}
				}
			}
			// finger cutouts
			for  (i = [-depth/2:fingerSize*2:depth/2 + fingerSize]) {
				translate([-fingerLength,i - (fingerSize/2) - (hingeFingerSlop/2),0]) {
					cube([fingerLength*2,fingerSize + hingeFingerSlop,height*2]);
				}
				if (depth/2 - i < (fingerSize * 1.5)) {
					translate([-fingerLength,i - (fingerSize/2) - (hingeFingerSlop/2),0]) {
						cube([fingerLength*2,depth,height*2]);
					}
				}
			}

			// center cutout
			translate([0, -depth/2, height]) {
				rotate([-90,0,0]) {
					cylinder(r = hingeInner /2 + hingeInnerSlop, h = depth);
				}
			}
		}
	}
}

