modelSources.QR_Code.scad:
//////////VARIABLE DECLARATIONS//////////

//preview[view:north east, tilt: top diagonal]

//QR Code Data Display Method
add_sub = 2; //[1:Subtract QR Geometry,2:Add QR Geometry]

//QR Code Mirroring. No: QR code is scanable from top of object. Yes: QR code is scanable from bottom of object. NOTE: Code is already flipped for iPhone cases so it will be scanable from back of iPhone case.
code_flip = 0; //[0:No,1:Yes]

//Select Main Object
obj = 1; //[0:QR data only,1:Rectangle,2:iPhone 4,3:iPhone 5,4:Rectangle with hole]

//Thickness option for iPhone cases
case_thickness = 1.8; //[1.8:Slim,2.4:Sturdy]

//For rectangles only (will also round perimeters)
round_corner = 1; //[1:No,2:Yes]

//Two opposite corners or all four corners
corner_num = 0; //[0:Two,1:Four]

//For rectangles and perimeters only (will also round perimeters) (mm)
corner_radius = 10; 

//Width of object (mm)
tag_width = 80;

//Height of object (mm)
tag_height = 80;

//Thickness of object (mm)
tag_thickness = 3;

//X Location of hole center (for rectangle with hole) (mm)
hole_x = 30;

//Y Location of hole center (for rectanlge with hole) (mm)
hole_y = 0;

//Radius of hole (for rectanlge with hole) (mm)
hole_r = 10;

//Distance from tag edge. "-1000" for none. (works with all models, but uses tag_width, tag_height plus perimeter dimensions for size) (mm)
perimeter = -1000;

//Wall thickness of perimeter (mm)
per_w = 3;

//Wall height of perimeter (mm)
per_h = 10;

//Scale multiplier for code (base size: 1mm cubes make each code block) (multiplier)
qr_scale = 1.6;

//(DO NOT PUT IN 0 customizer won't generate stl, instead put in a very small value like 0.001 for no tolerance) Use for making a positive and negative assembly (+val makes code blocks bigger) (mm)
qr_tolerance = 0.001;

//X location of QR code center (mm)
qr_x = 0;

//Y location of QR code center (mm)
qr_y = 0;

//Z location of bottom of QR code gemometry (mm)
qr_bottom = 1;

//Thickness of QR code (mm)
qr_thickness = 5;

//Rotate QR code around z-axis (deg)
qr_rotate = 0;

//Input from data generator for dimention of QR code (copy and paste from QR SIZE.txt)
qr_size = 41;

//Input raw QR data matrix here (copy and paste from QR DATA.txt) ("5" will make a rectangle the size of the QR code bounding box driven by qr_size value entered above. NOTE: rectangle will be slightly larger than actual code data due to "white" pixels around QR code in image)
qr_data = 5;

qr_num = qr_size*qr_size;


//////////GEOMETRY MANIPULATION//////////

//Just qr data
if (obj == 0)
{
	qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
	if (perimeter != -1000)
	{
		perimeter();
	}
}

//Basic rectangle tag
if (obj == 1)
{
	if (add_sub == 1)
	{
		difference()
		{
			rec_tag(tag_width, tag_height, tag_thickness);
			qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
		}
	}
	if (add_sub == 2)
	{
		union()
		{
			rec_tag(tag_width, tag_height, tag_thickness);
			qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
		}
	}
	if (perimeter != -1000)
	{
		perimeter();
	}
}

//iPhone 4
if(obj == 2)
{
	if (add_sub == 1)
	{
		difference()
		{
			iPhone4Case();
			translate([0,0,qr_thickness-.1])
			rotate([180,0,0])
			qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
		}
	}
	if (add_sub == 2)
	{
		union()
		{
			iPhone4Case();
			translate([0,0,qr_thickness-.1])
			rotate([180,0,0])
			qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
		}
	}
}


//iPhone 5
if(obj == 3)
{
	if (add_sub == 1)
	{
		difference()
		{
			iPhone5Case();
			translate([0,0,qr_thickness-.1])
			rotate([180,0,0])
			qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
		}
	}
	if (add_sub == 2)
	{
		union()
		{
			iPhone5Case();
			translate([0,0,qr_thickness-.1])
			rotate([180,0,0])
			qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
		}
	}
}


//Rectangle with hole
if (obj == 4)
{
	if (add_sub == 1)
	{
		difference()
		{
			rec_tag(tag_width, tag_height, tag_thickness);
			qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
			translate([hole_x, hole_y, 1])
			cylinder(h=(2*tag_thickness), r=hole_r, center=true);
		}
	}
	if (add_sub == 2)
	{
		difference()
		{
			union()
			{
				rec_tag(tag_width, tag_height, tag_thickness);
				qr_mover(qr_x, qr_y, qr_bottom, qr_rotate, qr_scale);
			}
			translate([hole_x, hole_y, 1])
			cylinder(h=(2*tag_thickness), r=hole_r, center=true);
		}
	}
	if (perimeter != -1000)
	{
		perimeter();
	}
}


//////////MODULE DEFINITIONS//////////

module qr_volume(size, num, data, thickness, tol)
{
	if (qr_data == 5)
	{
		color("Snow")
		translate([0, 0, thickness/2])
		cube([size, size, thickness], center=true);
	}
	else
	{
		color("DarkGrey")
		union()
		{
			for(i = [1:1:num])
			{
				if(data[i-1] == 1)
				{
					translate([(floor(i/size)-(qr_size/2)),(i-(size*floor(i/size))-1-(qr_size/2)), 0])
					cube([1+tol, 1+tol, thickness],center=[.5,.5,0]);
				}
			}
		}
	}
}

module qr_mover(x, y, z, rotate, scale)
{
	translate([x,y,z])
	rotate([0, 0, rotate])
	scale([scale, scale, 1])
	mirror([0, code_flip, 0])
	qr_volume(qr_size, qr_num, qr_data, qr_thickness, qr_tolerance);
}

module corner_rounder(w, h, t)
{
	for (c = [0:1:corner_num])
	{
		union()
		{
			mirror([0, c, 0])
			difference()
			{
				translate([w/2, h/2, t/2])
				cylinder(h=t*2, r=corner_radius, center=true);
				translate([(w/2)-corner_radius, (h/2)-corner_radius, t/2])
				cylinder(h=t*3, r=corner_radius, center=true);
			}
			mirror([0, c, 0])
			difference()
			{
				translate([-w/2, -h/2, t/2])
				cylinder(h=t*2, r=corner_radius, center=true);
				translate([-(w/2)+corner_radius, -(h/2)+corner_radius, t/2])
				cylinder(h=t*3, r=corner_radius, center=true);
			}
		}
	}
}

module rec_tag(t_w, t_h, t_t)
{
	difference()
	{
		translate([0, 0, (t_t/2)])
		cube([t_w, t_h, t_t], center=true);
		if (round_corner == 2)
		{
			corner_rounder(t_w, t_h, t_t);
		}
	}
}

module perimeter()
{
	difference()
	{
		rec_tag(tag_width+perimeter+per_w, tag_height+perimeter+per_w, per_h);
		translate([0, 0, -1])
		rec_tag(tag_width+perimeter, tag_height+perimeter, per_h+2);
	}
}




//////////MAKERBOT IPHONE CASE//////////


/*Non customizer variables*/
caseThickness = case_thickness;
caseTolerance = .2/1;

4width=58.55/1;	
4length=115.15/1;
4height=9.34/1;
4cornerR = 8.77/1;
4swidth=6.17/1;
4sthick=.6/1;

5width = 57.57/1;
5length = 122.83/1;
5height = 7.6/1;
5cornerR = 9.28/1;
5sthick = 1.44/1;
5swidth = 5height - 5sthick*1.5;

heightvar=.24/1;

homebuttonR = 5.6/1;
homebuttonD = homebuttonR*2;

top_bottom_opening_width = 50/1;
leftholelength = 25.43/1;
leftholeR = 2.4/1;
topholelength = 38.57/1;
topholeR = 2.5/1;
bottomholelength1 = 43.97/1;
bottomholelength2 = 26.05/1;
bottombigR = 1.53/1;
bottomsmallR = 1.15/1;

corner_resolution = 6/1;
circle_resolution = corner_resolution*4;

fudge = .05/1;


//MODULES

module iPhoneGlass(w, l, h, r)
{
	union(){
		cube([w,l-r*2,h],center = true);
		cube([w-r*2,l,h],center = true);
		//top right corner
		translate([w/2-r,l/2-r,0])
			cylinder(	h = h,
						r = r,
						center = true,
						$fn = circle_resolution);
		//top left corner
		translate([-(w/2-r),l/2-r,0])
			cylinder(	h = h,
						r = r,
						center = true,
						$fn = circle_resolution);
		//bottom right corner
		translate([w/2-r,-(l/2-r),0])
			cylinder(	h = h,
					 	r = r,
						center = true,
						$fn = circle_resolution);
		//bottom left corner
		translate([-(w/2-r),-(l/2-r),0])
			cylinder(	h = h,
						r = r,
						center = true, 
						$fn = circle_resolution);
	}
}

module iPhoneStrip(	w, l, h, r, sw, st)
{
	union(){
		cube([w+st*2,l-r*2,sw],center = true);
		cube([w-r*2,l+st*2,sw],center = true);
		//top right corner
		translate([w/2-r,l/2-r,0])
			cylinder(	h = sw,
						r = r+st,
						center = true,
						$fn = circle_resolution);
		//top left corner
		translate([-(w/2-r),l/2-r,0])
			cylinder(	h = sw,
						r = r+st,
						center = true,
						$fn = circle_resolution);
		//bottom right corner
		translate([w/2-r,-(l/2-r),0])
			cylinder(	h = sw,
						r = r+st,
						center = true,
						$fn = circle_resolution);
		//bottom left corner
		translate([-(w/2-r),-(l/2-r),0])
			cylinder(	h = sw,
						r = r+st,
						center = true,
						$fn = circle_resolution);
	}
}

module iPhoneCameraHole(w,h,r){
	hull(){
		translate([w/2,0,0])
			cylinder(h = h,r = r,center = true, $fn = circle_resolution);
		translate([-w/2,0,0])
			cylinder(h = h,r = r,center = true, $fn = circle_resolution);
	}
}


module iPhone5(w,l,h,cR,sw,st){
	hull(){
		iPhoneGlass(w,l,h,cR);
		iPhoneStrip(w,l,h,cR,sw,st);
	}
}


module iPhone4(w,l,h,cR,sw,st){
	union(){
		hull(){
			iPhoneGlass(w,l,sw+st,cR);
			iPhoneStrip(w,l,h,cR,sw,st);
		}
		iPhoneGlass(w,l,h,cR);
	}
}

module iPhone5Case(){
	translate([0,0,(5height+caseThickness)/2]){
		difference(){
			hull(){
				iPhoneGlass(5width+caseThickness*2,5length+caseThickness*2,5height+caseThickness,5cornerR+caseThickness);
				iPhoneStrip(5width+caseThickness*2,5length+caseThickness*2,5height+caseThickness*2,5cornerR+caseThickness,5swidth,5sthick);
			}
			iPhone5(5width-caseTolerance*3,5length-caseTolerance*2,5height+caseTolerance,5cornerR,5swidth+caseTolerance*2,5sthick+caseTolerance);
			translate([0,0,-5height*.5])
				iPhoneGlass(5width-caseThickness*2,5length-caseThickness*2,5height,5cornerR);
			translate([0,0,5height*.5])
				iPhoneGlass(5width-caseTolerance*3,5length-caseTolerance*2,5height+caseTolerance,5cornerR);
			translate([0,0,caseThickness/2])
			cube([44,5length+20,5height+caseThickness/2],center = true);
			translate([-5width/2-caseThickness*.8,30,4.5])
				rotate([90,0,90])
				scale([1,1,2])
				iPhoneCameraHole(30,caseThickness*2,8);
		}
		difference(){
			union(){
				intersection(){
					translate([0,0,-(5height/2 + caseThickness/4 + caseTolerance/4)])
						iPhoneGlass(5width-caseThickness*2+fudge,5length-caseThickness*2+fudge,caseThickness/2-caseTolerance/2,5cornerR-fudge);
				}
				translate([15,52.4,-(5height/2 + caseThickness/4)])
					iPhoneCameraHole(7.8,caseThickness/2,7.8+1.6);
			}
			translate([15,52.4,-(5height/2 + caseThickness/4)])
				scale([1,1,2])
				iPhoneCameraHole(7.8,caseThickness/2,7.8);
		}
	}	
}

module iPhone4Case(){
	translate([0,0,(4height+caseThickness)/2]){
		difference(){
			hull(){
				iPhoneGlass(4width+caseThickness*2,4length+caseThickness*2,4height+caseThickness,4cornerR+caseThickness);
				iPhoneStrip(4width+caseThickness*2,4length+caseThickness*2,4height+caseThickness*2,4cornerR+caseThickness,4swidth,4sthick);
			}
			iPhone4(4width-caseTolerance*3,4length-caseTolerance*2,4height+caseTolerance,4cornerR,4swidth+caseTolerance*2,4sthick+caseTolerance);
			translate([0,0,4height*.5])
				iPhoneGlass(4width-caseTolerance*3,4length-caseTolerance*2,4height,4cornerR);
			translate([0,0,-4height*.5])
				iPhoneGlass(4width-caseThickness*2,4length-caseThickness*2,4height,4cornerR);
			translate([0,0,caseThickness/2])
			cube([44,4length+20,4height+caseThickness/2],center = true);
			translate([-4width/2-caseThickness*.8,30,5])
				rotate([90,0,90])
				scale([1,1,2])
				iPhoneCameraHole(24,caseThickness*2,8);
		}
		difference(){
			union(){
				intersection(){
					translate([0,0,-(4height/2 + caseThickness/4 + caseTolerance/4)])
						iPhoneGlass(4width-caseThickness*2+fudge,4length-caseThickness*2+fudge,caseThickness/2-caseTolerance/2,4cornerR+fudge);	
				}
				translate([15,48.2,-(4height/2 + caseThickness/4)])
					iPhoneCameraHole(7.8,caseThickness/2,7.8+1.6);
			}
			translate([15,48.2,-(4height/2 + caseThickness/4)])
				scale([1,1,2])
				iPhoneCameraHole(7.8,caseThickness/2,7.8);
		}
	}	
}

modelSources.random_maze_cube_generator.scad:
x_blocks = 10; 
y_blocks = 10;
z_blocks = 10;
wall_thickness = 1;
wall_height = 2;
block_width = 5;
edge_enabled = "YES";

/*
 * constants, for clearness
 *
 */
 
// random directions, for picking up a direction to visit the next block
function PERMUTATION_OF_FOUR() = [
    [1, 2, 3, 4],
    [1, 2, 4, 3],
    [1, 3, 2, 4],
    [1, 3, 4, 2],
    [1, 4, 2, 3],
    [1, 4, 3, 2],
    [2, 1, 3, 4],
    [2, 1, 4, 3],
    [2, 3, 1, 4],
    [2, 3, 4, 1],
    [2, 4, 1, 3],
    [2, 4, 3, 1],
    [3, 1, 2, 4],
    [3, 1, 4, 2],
    [3, 2, 1, 4],
    [3, 2, 4, 1],
    [3, 4, 1, 2],
    [3, 4, 2, 1],
    [4, 1, 2, 3],
    [4, 1, 3, 2],
    [4, 2, 1, 3],
    [4, 2, 3, 1],
    [4, 3, 1, 2],
    [4, 3, 2, 1]
];

function NO_WALL() = 0;
function UP_WALL() = 1;
function RIGHT_WALL() = 2;
function UP_RIGHT_WALL() = 3;

function NOT_VISITED() = 0;
function VISITED() = 1;

/* 
 * modules for creating a maze
 *
 */

// give a [x, y] point and length. draw a line in the x direction
module x_line(point, length, thickness = 1) {
    offset = thickness / 2;
    translate([point[0] - offset, point[1] - offset, 0]) 
        square([length + thickness, thickness]);
}

// give a [x, y] point and length. draw a line in the y direction
module y_line(point, length, thickness = 1) {
    offset = thickness / 2;
    translate([point[0] - offset, point[1] - offset, 0])  
        square([thickness, length + thickness]);
}

// create the outer wall of maze
module maze_outer_wall(rows, columns, block_width = 5, wall_thickness = 1) {
    x_line([0, rows * block_width], columns * block_width, wall_thickness);
    y_line([0, block_width], (rows - 1) * block_width, wall_thickness);
}

// create the inner wall of maze
module maze_inner_wall(maze, block_width = 5, wall_thickness = 1) {
    for(i = [0:len(maze) - 1]) {
        cord = maze[i];
        x = (cord[0] - 1) * block_width;
        y = (cord[1] - 1) * block_width;
        v = cord[3];
        
        if(v == 1 || v == 3) {
            x_line([x, y], block_width, wall_thickness);
        }
        if(v == 2 || v == 3) {
            y_line([x + block_width, y], block_width, wall_thickness);
        }
    }  
}

// create a maze
module maze(rows, columns, maze_vector, block_width = 5, wall_thickness = 1) {
     maze_outer_wall(rows, columns, block_width, wall_thickness);
     maze_inner_wall(maze_vector, block_width, wall_thickness);
}

/* 
 * utilities functions
 *
 */

// comare the equality of [x1, y1] and [x2, y2]
function cord_equals(cord1, cord2) = cord1 == cord2;

// is the point visited?
function not_visited(cord, vs, index = 0) =
    index == len(vs) ? true : 
        (cord_equals([vs[index][0], vs[index][1]], cord) && vs[index][2] == 1 ? false :
            not_visited(cord, vs, index + 1));
            
// pick a direction randomly
function rand_dirs() =
    PERMUTATION_OF_FOUR()[round(rands(0, 24, 1)[0])]; 

// replace v1 in the vector with v2 
function replace(v1, v2, vs) =
    [for(i = [0:len(vs) - 1]) vs[i] == v1 ? v2 : vs[i]];
    
/* 
 * functions for generating a maze vector
 *
 */

// initialize a maze
function init_maze(rows, columns) = 
    [
	    for(c = [1 : columns]) 
	        for(r = [1 : rows]) 
		        [c, r, 0,  UP_RIGHT_WALL()]
	];
    
// find a vector in the maze vector
function find(i, j, maze_vector, index = 0) =
    index == len(maze_vector) ? [] : (
        cord_equals([i, j], [maze_vector[index][0], maze_vector[index][1]]) ? maze_vector[index] : find(i, j, maze_vector, index + 1)
    );

////
// NO_WALL = 0;
// UP_WALL = 1;
// RIGHT_WALL = 2;
// UP_RIGHT_WALL = 3;
function delete_right_wall(original_block) = 
    original_block == NO_WALL() || original_block == RIGHT_WALL() ? NO_WALL() : UP_WALL();

function delete_up_wall(original_block) = 
    (original_block == NO_WALL() || original_block == UP_WALL()) ? NO_WALL() : RIGHT_WALL();
    
function delete_right_wall_of(vs, is_visited, maze_vector) =
    replace(vs, [vs[0], vs[1] , is_visited, delete_right_wall(vs[3])] ,maze_vector);

function delete_up_wall_of(vs, is_visited, maze_vector) =
    replace(vs, [vs[0], vs[1] , is_visited, delete_up_wall(vs[3])] ,maze_vector);

function go_right(i, j, rows, columns, maze_vector) =
    go_maze(i + 1, j, rows, columns, delete_right_wall_of(find(i, j, maze_vector), VISITED(), maze_vector));
    
function go_up(i, j, rows, columns, maze_vector) =
    go_maze(i, j - 1, rows, columns, delete_up_wall_of(find(i, j, maze_vector), VISITED(), maze_vector));
    
function visit(v, maze_vector) =
    replace(v, [v[0], v[1], VISITED(), v[3]], maze_vector);
 
function go_left(i, j, rows, columns, maze_vector) =
    go_maze(i - 1, j, rows, columns, delete_right_wall_of(find(i - 1, j, maze_vector), NOT_VISITED(), maze_vector));
    
function go_down(i, j, rows, columns, maze_vector) =
    go_maze(i, j + 1, rows, columns, delete_up_wall_of(find(i, j + 1, maze_vector), NOT_VISITED(), maze_vector));
    
function go_maze(i, j, rows, columns, maze_vector) =
    look_around(i, j, rand_dirs(), rows, columns, visit(find(i, j, maze_vector), maze_vector));
    
function look_around(i, j, dirs, rows, columns, maze_vector, index = 0) =
    index == 4 ? maze_vector : 
        look_around( 
            i, j, dirs, 
            rows, columns, 
            build_wall(i, j, dirs[index], rows, columns, maze_vector), 
            index + 1
        ); 

function build_wall(i, j, n, rows, columns, maze_vector) = 
    n == 1 && i != columns && not_visited([i + 1, j], maze_vector) ? go_right(i, j, rows, columns, maze_vector) : ( 
        n == 2 && j != 1 && not_visited([i, j - 1], maze_vector) ? go_up(i, j, rows, columns, maze_vector)  : (
            n == 3 && i != 1 && not_visited([i - 1, j], maze_vector) ? go_left(i, j,rows, columns,  maze_vector)  : (
                n == 4 && j != rows && not_visited([i, j + 1], maze_vector) ? go_down(i, j, rows, columns, maze_vector) : maze_vector
            ) 
        )
    ); 

module maze_cube(blocks, block_width, wall_thickness, wall_height) {
    x_blocks = blocks[0];
    y_blocks = blocks[1];
    z_blocks = blocks[2];
    
    length = block_width * x_blocks + wall_thickness * 2;
    width = block_width * y_blocks + wall_thickness * 2;
    height = block_width * z_blocks + wall_thickness * 2;
   
   
    
   maze_vector1 = go_maze(1, 1, y_blocks, x_blocks, replace([1, 1, 0, UP_RIGHT_WALL()], [1, 1, 0, RIGHT_WALL()],
        replace([x_blocks, y_blocks, 0, UP_RIGHT_WALL()], [x_blocks, y_blocks, 0, UP_WALL()], init_maze(y_blocks, x_blocks))
    ));
    
    maze_vector2 = go_maze(1, 1, y_blocks, x_blocks, replace([x_blocks, 1, 0, UP_RIGHT_WALL()], [x_blocks, 1, 0, RIGHT_WALL()], init_maze(y_blocks, x_blocks)));
    
    maze_vector3 = go_maze(1, 1, x_blocks, z_blocks, replace([z_blocks, x_blocks, 0, UP_RIGHT_WALL()], [z_blocks, x_blocks, 0, UP_WALL()], init_maze(x_blocks, z_blocks)));
    
    maze_vector4 = go_maze(1, 1, z_blocks, x_blocks, replace([x_blocks, 1, 0, UP_RIGHT_WALL()], [x_blocks, 1, 0, UP_WALL()], init_maze(z_blocks, x_blocks)));
    
    maze_vector5 = go_maze(1, 1, z_blocks, y_blocks, replace([y_blocks, 1, 0, UP_RIGHT_WALL()], [y_blocks, 1, 0, RIGHT_WALL()], init_maze(z_blocks, y_blocks)));
    
    maze_vector6 = go_maze(1, 1, y_blocks, z_blocks,  replace([z_blocks, 1, 0, UP_RIGHT_WALL()], [z_blocks, 1, 0, RIGHT_WALL()], init_maze(y_blocks, z_blocks))); 
    
    
    cube([length, width, height]);
        
    // 1
    translate([wall_thickness, wall_thickness, -wall_height]) 
        linear_extrude(wall_height) 
        union() {
            y_line([0, 0], block_width);
            maze(y_blocks, x_blocks, maze_vector1, block_width, wall_thickness);
        }
                
    // 5
    translate([wall_thickness, wall_thickness, height]) 
         linear_extrude(wall_height) 
            maze(y_blocks, x_blocks, maze_vector2, block_width, wall_thickness);
    // 6       
    translate([length - wall_thickness, -wall_height, height - wall_thickness]) 
         rotate([90, 90, 180]) linear_extrude(wall_height) 
            maze(x_blocks, z_blocks, maze_vector3, block_width, wall_thickness);
    // 3
    translate([wall_thickness, width, height - wall_thickness]) 
        rotate([-90, 0, 0]) linear_extrude(wall_height) 
            maze(z_blocks, x_blocks, maze_vector4, block_width, wall_thickness);     
    // 4
    translate([-wall_height, width - wall_thickness, height - wall_thickness]) 
         rotate([90, 180, 90])linear_extrude(wall_height) 
            maze(z_blocks, y_blocks, maze_vector5, block_width, wall_thickness);
        
    // 2
    translate([length, width - wall_thickness, wall_thickness]) 
         rotate([0, -90, 180]) linear_extrude(wall_height) 
            maze(y_blocks, z_blocks, maze_vector6, block_width, wall_thickness);

            
    if(edge_enabled == "YES") {
        edge_square_width = 1.5 * wall_thickness + wall_height;
                
        translate([wall_thickness / 2 + block_width, -wall_height, -wall_height]) 
            cube([block_width * (x_blocks - 1) + 1.5 * wall_thickness + wall_height, edge_square_width, edge_square_width]);
         
        translate([0, width - 1.5 * wall_thickness, -wall_height]) 
            cube([length + wall_height, edge_square_width, edge_square_width]);        

        translate([-wall_height , -wall_height, -wall_height]) 
            cube([edge_square_width, y_blocks * block_width + wall_height * 2 + wall_thickness * 2, edge_square_width]);

        translate([x_blocks * block_width + wall_thickness / 2, -wall_height, -wall_height]) 
            cube([edge_square_width, (y_blocks - 1) * block_width + wall_height + wall_thickness * 1.5, edge_square_width]);        
            
        // 
  
        translate([-wall_height, -wall_height, height - edge_square_width + wall_height]) 
            cube([block_width * (x_blocks - 1) + 1.5 * wall_thickness + wall_height, edge_square_width, edge_square_width]);
            
          
        translate([-wall_height, width - 1.5 * wall_thickness, height - edge_square_width + wall_height]) 
            cube([length + wall_height - wall_thickness / 2, edge_square_width, edge_square_width]);        
            
        translate([-wall_height , block_width + wall_thickness / 2, height - edge_square_width + wall_height]) 
            cube([edge_square_width, (y_blocks - 1) * block_width , edge_square_width]);
            

        translate([x_blocks * block_width + wall_thickness / 2, -wall_height, height - edge_square_width + wall_height]) 
            cube([edge_square_width, y_blocks * block_width + wall_height * 2 + wall_thickness * 2, edge_square_width]);     

        //

        
        translate([-wall_height, -wall_height, 0])
            cube([edge_square_width, edge_square_width, height]);          
  
        translate([length - 1.5* wall_thickness, -wall_height, 0])
            cube([edge_square_width, edge_square_width, height]);           
            
                
        translate([-wall_height, width - 1.5 * wall_thickness, 0])
            cube([edge_square_width, edge_square_width, height - block_width - wall_thickness / 2]);

        translate([length - 1.5 * wall_thickness, width - 1.5 * wall_thickness, 0])
            cube([edge_square_width, edge_square_width, height - block_width - wall_thickness / 2]);     
    }        
}
    
/*
 * create a maze
 *
 */

maze_cube([x_blocks, y_blocks, z_blocks], block_width, wall_thickness, wall_height);

modelSources.Retro_Word_Pen.scad:
use <MCAD/fonts.scad>

// Word to display on the pen
word = "BrandonW6";

// Scale multipler for font size
font_scale = 2.1	;

// Character Spacing (for some reason this value is buggy using the customizer)
font_spacing = 0.81; 

// The diameter of end hole
pen_inner_diameter = 4.3 *1;
pen_inner_radius = pen_inner_diameter / 2;

// length of the entire pen
pen_length = 130; //

// Overal thickness of the pen
pen_thickness = 8*1;


/////////////////////////////////////////
//////////////////////////////////



module penword()
{

thisFont=8bit_polyfont();
x_shift=thisFont[0][0] * font_spacing;
y_shift=thisFont[0][1];

	theseIndicies=search(word,thisFont[2],1,1);
	wordlength = (len(theseIndicies))* x_shift;
	
	difference() {

		union() {

// Create the Text //
			scale([font_scale,font_scale,1]){
			for( j=[0:(len(theseIndicies)-1)] ) 
				translate([ j*x_shift + 1, -y_shift/2 ,-pen_thickness/2]) 
				{
					linear_extrude(height=pen_thickness) polygon(points=thisFont[2][theseIndicies[j]][6][0],paths=thisFont[2][theseIndicies[j]][6][1]);
				}
			}
			
// Main body
			translate([1*font_scale+3	,-y_shift*.45,-pen_thickness/2]) cube([pen_length - 3,y_shift * 0.9,pen_thickness * 0.8]);

// Pen Tip
			rotate(a=[0,90,0]) 
				{
					translate([pen_thickness*0.1,0,0	])	cylinder(h = 5, r = pen_thickness*.4, $fn=50);
					translate([pen_thickness*0.1,0,-5	])	cylinder(h = 5, r1 = 1, r2 = pen_thickness*.4, $fn=50);
				}			
		}
// Cut outs
			translate([0,-pen_inner_diameter/2,-pen_thickness/2+pen_thickness*.15]) cube([pen_length + 20,pen_inner_diameter,pen_inner_diameter]);
			rotate(a=[0,90,0])translate([pen_thickness*.1,0,-15])	cylinder(h = 30, r = pen_inner_radius, $fn=100);
	}
}




penword();

modelSources.SecretHeart.scad:
// All-at-once Secret Heart Box

assembly();
//animation();

//First word
word1="";
//Second word
word2="";
//Height of words
fontsize=6;
Font = "write/Letters.dxf";//["write/Letters.dxf":Basic,"write/orbitron.dxf":Futuristic,"write/BlackRose.dxf":Fancy]
//Length of parallel midsection
L=40;
//Width of flat face
W=35;
//Height of box
H=25;
//Space between hinges
x_hinge=23;
//Wall Thickness
T=0.8;
//Depth of sliding nubs
nub=2;//[1:3]
//Tolerance between moving parts
tol=0.4;
//Smoother renders slower
quality=1;//[1:Draft,2:Medium,4:Fine]

use <utils/build_plate.scad>
use <write/Write.scad> 

//for display only, doesn't contribute to final object
build_plate_selector = 0; //[0:Replicator 2,1: Replicator,2:Thingomatic,3:Manual]
//when Build Plate Selector is set to "manual" this controls the build plate x dimension
build_plate_manual_x = 100; //[100:400]
//when Build Plate Selector is set to "manual" this controls the build plate y dimension
build_plate_manual_y = 100; //[100:400]

build_plate(build_plate_selector,build_plate_manual_x,build_plate_manual_y);

$fa=12/quality;
$fs=2/quality;
phi=atan(W/L);// heart angle
R=H/2-2*nub-3*T;// clasp radius
R1=H/2-2*nub;// cleave radius
t1=1-2*abs($t-0.5);// makes time loop back and forth

module animation()
assign(phi= t1<0.5 ? 0 : (t1-0.5)*2*90,psi= t1<0.5 ? (t1-0.5)*2*180 : 0){
	LowerLeft();
	translate([0,R1*sqrt(2)+H/2+nub,-H/2+nub])rotate([-phi,0,0])
		translate(-[0,R1*sqrt(2)+H/2+nub,-H/2+nub])UpperLeft();
	rotate([psi,0,0]){
		translate([0,R1*sqrt(2)+H/2+nub,-H/2+nub])rotate([-phi,0,0])
			translate(-[0,R1*sqrt(2)+H/2+nub,-H/2+nub])UpperRight();
		LowerRight();
	}
}

module assembly()
translate([0,0,H/2]){
	LowerLeft();
	UpperLeft();
	LowerRight();
	UpperRight();
}

module UpperLeft()
render()
union(){
	difference(){
		cleave(lower=false)Left();
		translate([-3/2*tol-nub-T,0,0])hingeGap();
		translate([-x_hinge,0,0])mirror([1,0,0])hingeGap();
	}
	translate([-L/2*sin(phi),L/2*cos(phi),H/2+0.49])write(word1,t=1,h=fontsize,center=true,font=Font);
}

module LowerLeft()
render()
union(){
	cleave(lower=true)Left();
	difference(){
		clasp(inside=1);
		translate([0,0,-R+T])rotate([0,-45,0])translate([0,0,-H])cube(2*H,center=true);
	}
	translate([-3/2*tol-nub-T,0,0])hinge();
	translate([-x_hinge,0,0])mirror([1,0,0])hinge();
	brace();
}

module UpperRight()
render()
union(){
	difference(){
		cleave(lower=false)Right();
		translate([3/2*tol+nub+T,0,0])mirror([1,0,0])hingeGap();
		translate([x_hinge,0,0])hingeGap();
		clasp(inside=0);
	}
	translate([L/2*sin(phi),L/2*cos(phi),H/2+0.49])write(word2,t=1,h=fontsize,center=true,font=Font);
}

module LowerRight()
render()
difference(){
	union(){
		cleave(lower=true)Right();
		translate([nub+T,0,T+0.5-H/2])translate([6,5,0])monogram(h=1.01);
		translate([3/2*tol+nub+T,0,0])mirror([1,0,0])hinge();
		translate([x_hinge,0,0])hinge();
		mirror([1,0,0])brace();
	}
	translate([nub+T+tol/2,0,0])rotate([0,90,0])cylinder(r=R+nub+T,h=tol);
	clasp(inside=0);
}

module brace()
intersection(){
	rotate([45,0,0])translate([0,R1,0])difference(){
		cylinder(r=nub+2*T+tol*3/2,h=3*H,center=true);
		translate([L-nub-T,0,0])cube(2*L,center=true);
		translate([L-nub-T-tol*3/2,L,0])cube(2*L,center=true);
	}
	difference(){
		translate([0,0,0])cube([L,2*(R1*sqrt(2)+H/2+nub),H-T],center=true);
		difference(){
			translate([0,0,L+H/2-2*T])cube(2*L,center=true);
			rotate([-45,0,0])cube([2*L,2*L,2*R1],center=true);
		}
	}
}

module cleave(lower=true)
assign(y = lower==true ? L+R1 : -L+R1+tol)
difference(){
	child(0);
	rotate([45,0,0])translate([0,y,0])cube(2*L,center=true);
}

module Right()
difference(){
	union(){
		mirror([1,0,0])hollowbase();
		rotate([-45,0,0])translate([tol/2+.01,0,H/2-nub])point();
	}
	rotate([45,0,0])rotate([0,90,0])track();
}

module Left()
difference(){
	union(){
		hollowbase();
		rotate([-45,0,0])translate([-tol/2-.01,0,H/2-nub])rotate([0,180,0])point();
	}
	rotate([45,0,0])rotate([0,-90,0])track();
}

module clasp(inside=0)
rotate([0,90,0])translate([0,0,-tol/2-.01])
	cylinder(r1=R-tol-tol*inside,r2=R+nub+T-tol*inside,h=nub+T+tol+.02);

module point()
rotate([0,-90,0])cylinder(r1=nub,r2=0,h=nub);

module track()
union(){
	difference(){
		union(){
			rotate_extrude()translate([H/2-nub,-tol/2])rotate(45)square(nub*sqrt(2),center=true);
			translate(-[0,nub-H/2,0])cylinder(r1=nub,r2=0,h=nub);
		}
		translate([H+tol/2,0,0])cube(2*H,center=true);
	}
	translate([0,nub-H/2,0])cylinder(r1=nub,r2=0,h=nub);
}

module hollowbase()
difference(){
	base(inside=0);
	difference(){
		base(inside=1);
		translate([-nub-T,0,0])hinge();
		translate([-L-x_hinge,R1*sqrt(2)+H/2,-H/2])cube([L,2*nub,nub]);
		translate([-L-x_hinge,R1*sqrt(2)+H/2+nub,-H/2+nub])
			rotate([0,90,0])cylinder(r=nub,h=L);
	}
}

module hinge()
translate([-nub/2,R1*sqrt(2)+H/2,-H/2+nub])
difference(){
	union(){
		translate([0,-2*nub,0])cube([nub,6*nub,2*nub],center=true);
		translate([0,nub,0])rotate([0,90,0])cylinder(r=nub,h=nub,center=true);
		translate([nub/2-.01,nub,0])rotate([0,90,0])cylinder(r1=nub,r2=0,h=nub);
	}
	translate([0,-6*nub,2*nub])rotate([45,0,0])cube(6*nub,center=true);
}

module hingeGap()
translate([-nub/2,R1*sqrt(2)+H/2,-H/2+nub])
union(){
	translate([0,tol-nub,0])cube([nub+2*tol,6*nub,2*nub+2*tol],center=true);
	translate([nub/2+tol-.01,nub,0])rotate([0,90,0])cylinder(r1=nub,r2=0,h=nub);
}

module base(inside=0)
assign(W=W-2*T*inside)
intersection(){
	rotate([0,0,90+phi])union(){
		cube([L,W,2*H],center=true);
		translate([L/2,0,0])cylinder(r=W/2,h=2*H,center=true);
		translate([0,W/2-H/2,0])rotate([0,90,0])cylinder(r=H/sqrt(2),h=L,center=true);
		for(i=[-1,1])translate([i*L/2,0,0])
			rotate_extrude(convexity=2)difference(){
				translate([W/2-H/2,0])circle(r=H/sqrt(2));
				translate([-H,0])square(2*H,center=true);
			}
	}
	translate([-L-(nub+T)*inside-tol/2,0,0])cube([2*L,2*L,H-2*T*inside],center=true);
}

module monogram(h=1)
linear_extrude(height=h,center=true)
translate(-[3,2.5])union(){
	difference(){
		square([4,5]);
		translate([1,1])square([2,3]);
	}
	square([6,1]);
	translate([0,2])square([2,1]);
}

