difference(){
    cleave(lower=false)Left();
    translate([-3/2*tol-nub-T,0,0])hingeGap();
    translate([-x_hinge,0,0])mirror([1,0,0])hingeGap();
    #translate([-L/2*sin(phi)-.05*W,L/2*cos(phi),H/2])letter(first);
