module hull_of_object(textstr1, textstr2, textstr3, textsize1, textsize2, textsize3, add_a_special_character,paperheight)
{
    //rotate([0,(direction=="up"?1:-1)*90,0])scale([1,(direction=="up"?1:-1),1])
        linear_extrude(height=paperheight/2,convexity = 10)
            hull()
                writetext(textstr1, textstr2, textstr3, textsize1, textsize2, textsize3, add_a_special_character,1);
}

module square_hull_of_object(textstr1, textstr2, textstr3, textsize1, textsize2, textsize3, add_a_special_character,baseheight)
{
    
    minkowski()
    {
        translate([-border_side,0,0])
            rotate ([0,90,0])
                linear_extrude(height = 2*border_side,convexity = 2)
                    projection(cut = false)
                        rotate([0,-90,0])
                            hull_of_object(textstr1, textstr2, textstr3, textsize1, textsize2, textsize3, add_a_special_character,baseheight);
        
        translate([0,border_topdown,0])rotate ([90,0,0])
                linear_extrude(height = 2*border_topdown,convexity = 2)
                    projection(cut = false)
                        rotate([-90,0,0])
                            hull_of_object(textstr1, textstr2, textstr3, textsize1, textsize2, textsize3, add_a_special_character,baseheight);
    }
}

